CREATE TABLE connectivity_tokens(id INTEGER PRIMARY KEY,name TEXT NOT NULL,hash TEXT NOT NULL UNIQUE,scopes TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE connectivity_runs(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,status TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE connectivity_mail(id INTEGER PRIMARY KEY,identity TEXT NOT NULL UNIQUE,sender TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,received_at TEXT NOT NULL,task_id INTEGER REFERENCES tasks(id) ON DELETE SET NULL,state TEXT NOT NULL DEFAULT 'preview' CHECK(state IN ('preview','accepted','ignored')));
CREATE TABLE connectivity_events(id INTEGER PRIMARY KEY,provider TEXT NOT NULL,remote_id TEXT NOT NULL,appointment_id INTEGER REFERENCES planner_appointments(id) ON DELETE SET NULL,remote_version TEXT NOT NULL DEFAULT '',local_hash TEXT NOT NULL DEFAULT '',UNIQUE(provider,remote_id));
CREATE TABLE connectivity_macros(id INTEGER PRIMARY KEY,name TEXT NOT NULL,actions TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)),run_at TEXT NOT NULL DEFAULT '09:00',last_slot TEXT);
CREATE TABLE connectivity_script_runs(id INTEGER PRIMARY KEY,macro_id INTEGER REFERENCES connectivity_macros(id) ON DELETE SET NULL,slot TEXT NOT NULL,status TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(macro_id,slot));
CREATE TABLE connectivity_window_time(id INTEGER PRIMARY KEY,recorded_at TEXT NOT NULL,process TEXT NOT NULL,category TEXT NOT NULL,seconds INTEGER NOT NULL CHECK(seconds BETWEEN 1 AND 300),identity TEXT NOT NULL UNIQUE);
